@MainActor final class TPPreferences: ObservableObject {
    private let key: String
    private let defaults: UserDefaults
    @Published private var values: JSON
    init(role: String = "director", defaults: UserDefaults = .standard) {
        self.defaults = defaults
        key = "vshook.native.teleprompt.settings." + role
        values = defaults.data(forKey: key).flatMap { try? JSONDecoder().decode(JSON.self, from: $0) } ?? [:]
    }
    func settings(_ slot: Int) -> JSON {
        let preset = values["preset\(slot)"].string == "day" ? "day" : "night"
        var result = TPSchema.data["defaults"].merging(preset == "day" ? TPSchema.data["day"] : [:]).merging(values["\(slot).\(preset)"]).merging(["preset": .string(preset)])
        result["chordScale"] = .number(min(50, max(10, result["chordScale"].double)))
        return result
    }
    func set(_ field: String, _ value: JSON, slot: Int) {
        if field == "preset" { values["preset\(slot)"] = value }
        else { let k = "\(slot).\(settings(slot)["preset"].string)"; values[k] = values[k].merging(.object([field:value])) }
        persist()
    }
    var notice: JSON { TPSchema.data["notice"].merging(values["notice"]) }
    func setNotice(_ field: String, _ value: JSON) { values["notice"] = values["notice"].merging(.object([field:value])); persist() }
    func control(_ id: String, tablet: Bool) -> Bool { values[tablet ? "controls.tablet" : "controls.phone"][id].bool }
    func toggleControl(_ id: String, tablet: Bool) {
        let k = tablet ? "controls.tablet" : "controls.phone"
        values[k] = values[k].merging(.object([id: .bool(!values[k][id].bool)])); persist()
    }
    private func persist() { if let data = try? JSONEncoder().encode(values) { defaults.set(data, forKey: key) } }
}
